    let gn3 = Arc::clone(&g_n);
    let h3 = std::thread::spawn(move || notifier(&m3, &cv3, &g12_3, &gn3));

    h1.join().unwrap();
    h2.join().unwrap();
    h3.join().unwrap();

    println!("DONE waiters=0");
}
